package com.game_manager.gm.machine;
import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;import com.game_manager.gm.auth.RateLimitService;import com.game_manager.gm.common.security.Role;import com.game_manager.gm.gamingsession.*;import com.game_manager.gm.gamingsession.command.StationCommandRepository;import com.game_manager.gm.machine.dto.MachineDtos.SessionLoginRequest;import com.game_manager.gm.security.JwtService;import com.game_manager.gm.station.GamingStationProfileRepository;import com.game_manager.gm.user.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.security.crypto.password.PasswordEncoder;
class MachineSessionLoginScopeTest {
 @Test void customerLoginUsesOnlyActiveSessionOnAuthenticatedStation(){UUID identity=UUID.randomUUID(),station=UUID.randomUUID(),customerId=UUID.randomUUID();MachinePrincipal machine=new MachinePrincipal(identity,station,1);MachinePrincipalProvider principal=mock(MachinePrincipalProvider.class);when(principal.require()).thenReturn(machine);GamingSessionRepository sessions=mock(GamingSessionRepository.class);GamingSession session=new GamingSession();session.setId(UUID.randomUUID());session.setCustomerId(customerId);session.setResourceId(station);session.setStartedAt(Instant.parse("2026-08-16T10:00:00Z"));session.setEndsAt(Instant.parse("2026-08-16T12:00:00Z"));when(sessions.findByResourceIdAndStatus(station,GamingSessionStatus.ACTIVE)).thenReturn(Optional.of(session));User customer=new User();customer.setId(customerId);customer.setName("Customer");customer.setEmail("customer@example.com");customer.setPasswordHash("hash");customer.setRole(Role.CUSTOMER);customer.setActive(true);UserRepository users=mock(UserRepository.class);when(users.findById(customerId)).thenReturn(Optional.of(customer));PasswordEncoder passwords=mock(PasswordEncoder.class);when(passwords.matches("secret", "hash")).thenReturn(true);MachineLoginAttemptWriter writer=mock(MachineLoginAttemptWriter.class);MachineProtocolService service=service(sessions,principal,users,passwords,writer);var result=service.sessionLogin(new SessionLoginRequest("customer@example.com","secret"));assertThat(result.stationId()).isEqualTo(station);assertThat(result.sessionId()).isEqualTo(session.getId());verify(sessions).findByResourceIdAndStatus(station,GamingSessionStatus.ACTIVE);verify(writer).write(eq(machine),eq(session.getId()),eq(customerId),anyString(),eq(StationSessionLoginOutcome.SUCCESS));}

 @Test void guestTicketIsStationBoundTimeLimitedAndCannotAuthenticateRegisteredSessions() {
  UUID station=UUID.randomUUID();MachinePrincipalProvider principal=mock(MachinePrincipalProvider.class);when(principal.require()).thenReturn(new MachinePrincipal(UUID.randomUUID(),station,1));
  GamingSessionRepository sessions=mock(GamingSessionRepository.class);GamingSession guest=new GamingSession();guest.setId(UUID.randomUUID());guest.setResourceId(station);guest.setGuestName("Guest 1");guest.setEndsAt(Instant.parse("2026-08-16T11:30:00Z"));
  when(sessions.findByResourceIdAndStatus(station,GamingSessionStatus.ACTIVE)).thenReturn(Optional.of(guest));
  UserRepository users=mock(UserRepository.class);MachineProtocolService service=service(sessions,principal,users,mock(PasswordEncoder.class),mock(MachineLoginAttemptWriter.class));
  var result=service.guestLogin(new com.game_manager.gm.machine.dto.MachineDtos.SessionLogoutRequest(guest.getId()));assertThat(result.customerId()).isNull();assertThat(result.customerName()).isEqualTo("Guest 1");
  org.assertj.core.api.Assertions.assertThatThrownBy(()->service.guestLogin(new com.game_manager.gm.machine.dto.MachineDtos.SessionLogoutRequest(UUID.randomUUID()))).isInstanceOf(com.game_manager.gm.common.error.ApplicationException.class);
  guest.setMoveTargetId(UUID.randomUUID());org.assertj.core.api.Assertions.assertThatThrownBy(()->service.guestLogin(new com.game_manager.gm.machine.dto.MachineDtos.SessionLogoutRequest(guest.getId()))).isInstanceOf(com.game_manager.gm.common.error.ApplicationException.class);guest.setMoveTargetId(null);
  guest.setCustomerId(UUID.randomUUID());org.assertj.core.api.Assertions.assertThatThrownBy(()->service.guestLogin(new com.game_manager.gm.machine.dto.MachineDtos.SessionLogoutRequest(guest.getId()))).isInstanceOf(com.game_manager.gm.common.error.ApplicationException.class);guest.setCustomerId(null);
  guest.setEndsAt(Instant.parse("2026-08-16T10:30:00Z"));org.assertj.core.api.Assertions.assertThatThrownBy(()->service.guestLogin(new com.game_manager.gm.machine.dto.MachineDtos.SessionLogoutRequest(guest.getId()))).isInstanceOf(com.game_manager.gm.common.error.ApplicationException.class);
  verifyNoInteractions(users);
 }
 private MachineProtocolService service(GamingSessionRepository sessions,MachinePrincipalProvider principal,UserRepository users,PasswordEncoder passwords,MachineLoginAttemptWriter writer){return new MachineProtocolService(mock(StationEnrollmentTokenRepository.class),mock(StationMachineIdentityRepository.class),mock(StationAuthChallengeRepository.class),mock(StationHeartbeatRepository.class),mock(GamingStationProfileRepository.class),sessions,mock(StationCommandRepository.class),principal,mock(JwtService.class),mock(RateLimitService.class),Clock.fixed(Instant.parse("2026-08-16T10:30:00Z"),ZoneOffset.UTC),users,passwords,writer,mock(com.game_manager.gm.gamingsession.command.StationCommandWriter.class));}
}
